// Real token validation (Phase 2B fix)
// Token from env credential, exact match only, reject missing/wrong, never log
const headers = $input.first().json.headers || $json.headers || {};
const body = $input.first().json.body || $json.body || $json;

const expected = ($env.N8N_WEBHOOK_TOKEN || $env.N8N_CALLBACK_TOKEN || '').trim();
if (!expected) {
  throw new Error('Server misconfigured: shared token not set in n8n env');
}
const authHeader = (headers['authorization'] || '').trim();
const bearer = authHeader.toLowerCase().startsWith('bearer ') ? authHeader.slice(7).trim() : '';
const supplied = (headers['x-n8n-token'] || headers['x-callback-token'] || bearer || '').trim();
if (!supplied) {
  throw new Error('Missing authentication token - X-N8N-Token required');
}
if (supplied !== expected) {
  throw new Error('Invalid authentication token');
}

// No full_log defense
const payloadStr = JSON.stringify(body).toLowerCase();
if (payloadStr.includes('full_log')) {
  throw new Error('Security violation: payload must not contain full_log');
}

const payload = body.payload ? body.payload : body;
return { json: payload };

// Format high-severity notification with SLA context
const alert = $input.first().json;
const severity = (alert.severity || 'critical').toUpperCase();
const triageBase = $env.TRIAGE_API_BASE_URL || 'http://triage-api:8000';
const feedbackUrl = (alert.investigation_links && alert.investigation_links.feedback_url) || `${triageBase}/api/v1/alerts/${alert.alert_id}/feedback`;
const statusUrl = `${triageBase}/api/v1/alerts/${alert.alert_id}/feedback/status`;

const subject = `[SOC][${severity}][ESCALATION] Alert ${alert.alert_id} requires immediate review`;
const bodyText = `
*** HIGH SEVERITY ESCALATION ***
Alert ID: ${alert.alert_id}
Severity: ${severity}
Score: ${alert.score}
Decision: ${(alert.decision && alert.decision.severity) || 'SEV1'}
Rule: ${alert.rule}
IOCs: ${JSON.stringify(alert.iocs || {})}

Investigation:
- SIEM: ${(alert.investigation_links && alert.investigation_links.siem_search_url) || 'n/a'}
- Timeline: ${(alert.investigation_links && alert.investigation_links.timeline_url) || 'n/a'}
- Feedback: ${feedbackUrl}
- Status (GET): ${statusUrl}

SLA: 15m ack required. If not acknowledged, auto-escalates to L2.

Note: contain_requested creates an approval-required request; no containment action is executed. Human approval required, no autonomous containment.
`;

return {
  json: {
    ...alert,
    _escalation: {
      subject,
      bodyText,
      feedbackUrl,
      statusUrl,
      escalated_at: new Date().toISOString(),
      sla_minutes: 15
    }
  }
};
